from specflow.refmodel.temporal import after, eventually, throughout, worst

def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    applies = _holds({"ena": 1, "nReset": 1, "rst": 0})
    closes = _any([{"cmd_ack": 1}, {"al": 1}])
    windows = after(trace, applies, until=closes)
    follows = True  # normalized["activation"]["effect_follows"]

    verdicts = []
    for w in windows:
        verdicts.append(throughout(
            w,
            lambda r: r["outputs"].get("scl_o") == 0 and r["outputs"].get("sda_o") == 0,
            after_activation=follows))

        if w.closed and w.rows and w.rows[-1]["outputs"].get("cmd_ack") == 1:
            verdicts.append(eventually(
                w,
                lambda r: r["outputs"].get("scl_oen") == 0 or r["outputs"].get("sda_oen") == 0,
                after_activation=follows, strong=True))

    return worst(verdicts)

from specflow.refmodel.temporal import after, eventually, worst

def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    def _any(alts):
        preds = [_holds(a) for a in alts]
        return lambda row: any(p(row) for p in preds)

    closes = _any([{"cmd_ack": 1}, {"al": 1}])
    follows = True  # normalized activation.effect_follows

    def _windows_for(cmd_value):
        activation = _holds({"cmd": cmd_value, "ena": 1, "nReset": 1, "rst": 0})
        return after(trace, activation, until=closes)

    verdicts = []

    # START (cmd==1): the sequence pulls SDA low, then pulls SCL low
    # (sec. 11) -- both enables are expected to go low at some point.
    for w in _windows_for(1):
        verdicts.append(eventually(w, lambda r: r["outputs"]["scl_oen"] == 0,
                                    after_activation=follows, strong=True))
        verdicts.append(eventually(w, lambda r: r["outputs"]["sda_oen"] == 0,
                                    after_activation=follows, strong=True))

    # STOP (cmd==2): SDA is driven low, then SCL is released and stays
    # released for the rest of the sequence -- never re-driven low
    # (sec. 12) -- so only sda_oen's low assertion is checked.
    for w in _windows_for(2):
        verdicts.append(eventually(w, lambda r: r["outputs"]["sda_oen"] == 0,
                                    after_activation=follows, strong=True))

    # READ (cmd==8): SDA stays released throughout for the slave to drive;
    # only SCL is actively pulled low again to end the sample window
    # (sec. 13) -- no sda_oen expectation.
    for w in _windows_for(8):
        verdicts.append(eventually(w, lambda r: r["outputs"]["scl_oen"] == 0,
                                    after_activation=follows, strong=True))

    # WRITE (cmd==4): SCL is always pulled low again to end the bit; sda_oen
    # is only actively driven low when din==0 -- when din==1 the bit is
    # transmitted by releasing SDA and it must stay released for the
    # arbitration check, so no low assertion is expected there (sec. 14).
    for w in _windows_for(4):
        verdicts.append(eventually(w, lambda r: r["outputs"]["scl_oen"] == 0,
                                    after_activation=follows, strong=True))
        if w.value("din") == 0:
            verdicts.append(eventually(w, lambda r: r["outputs"]["sda_oen"] == 0,
                                        after_activation=follows, strong=True))

    return worst(verdicts)

from specflow.refmodel.temporal import after, eventually, worst

def _holds(cond):
    def p(row):
        return all(
            row["outputs"].get(k, row["inputs"].get(k)) == v
            for k, v in cond.items())
    return p

def _any(alts):
    preds = [_holds(a) for a in alts]
    return lambda row: any(p(row) for p in preds)

def decide(trace):
    activation = _holds({"cmd": 1, "ena": 1, "nReset": 1, "rst": 0})
    closes = _any([{"cmd_ack": 1}, {"al": 1}])
    windows = after(trace, activation, until=closes)
    return worst([
        eventually(w, lambda r: r["outputs"].get("sda_oen") == 1, after_activation=True)
        for w in windows
    ])

from specflow.refmodel.temporal import after, eventually, edges, worst


def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row["outputs"].get(k, row["inputs"].get(k)) == v
                for k, v in cond.items())
        return p

    rose = edges(trace, "scl_oen", "rise")
    al_rose = edges(trace, "al", "rise")

    # Trigger: the scl_oen 0->1 edge that begins a WRITE bit's high phase --
    # not merely cmd==4, which would also match a leftover scl_oen==1 left
    # over from before this bit's high phase ever began.
    def opens(row):
        return (row["edge"] in rose
                and _holds({"cmd": 4, "din": 1, "ena": 1,
                            "nReset": 1, "rst": 0})(row))

    # Close the window on ORDINARY completion only. REQ-0073 describes the
    # high phase terminating in a low pull followed by command completion;
    # a transaction instead cut short by arbitration loss is a different
    # occurrence and is filtered out below, not folded into this boundary.
    windows = after(trace, opens, until=_holds({"cmd_ack": 1}))
    if not windows:
        return worst([])

    results = []
    for w in windows:
        # Did a FRESH arbitration-loss (the al 0->1 TRANSITION, not a
        # sticky level left over from an earlier, unrelated bit -- al stays
        # 1 until reset) occur in this window before scl_oen ever read 0?
        # If so, this occurrence's high phase ended in an abort, not the
        # normal termination REQ-0073 describes, and it is excluded rather
        # than judged.
        aborted = False
        for r in w.rows:
            if r["outputs"].get("scl_oen") == 0:
                break
            if r["edge"] in al_rose:
                aborted = True
                break
        if aborted:
            continue

        results.append(
            eventually(w, lambda r: r["outputs"]["scl_oen"] == 0,
                       after_activation=True, strong=True))

    if not results:
        return (None, None,
                "every WRITE-bit high phase in this trace was cut short by "
                "arbitration loss before scl_oen asserted low; REQ-0073 "
                "does not cover that case")

    return worst(results)

def decide(trace):
    # normalized.activation.opens_on: {scl_oen: 0} or {sda_oen: 0} -- "an
    # output-enable is driven low". This is a same-row value relation
    # (section: "X causes Y"), not a transaction that has to close with a
    # later release, so every qualifying row is decided on its own; no
    # after/until window is needed or wanted here.
    scl_rows = [r for r in trace if r["outputs"].get("scl_oen") == 0]
    sda_rows = [r for r in trace if r["outputs"].get("sda_oen") == 0]

    if not scl_rows and not sda_rows:
        return (None, None,
                'neither scl_oen nor sda_oen was ever driven low in this trace')

    for r in scl_rows:
        if r["outputs"].get("scl_o") != 0:
            return (False, r["edge"],
                     'scl_oen == 0 (SCL actively driven low) but scl_o != 0')
    for r in sda_rows:
        if r["outputs"].get("sda_o") != 0:
            return (False, r["edge"],
                     'sda_oen == 0 (SDA actively driven low) but sda_o != 0')

    return (True, None,
            f'{len(scl_rows)} row(s) with scl_oen==0 and {len(sda_rows)} row(s) '
            'with sda_oen==0 all showed the corresponding constant-low drive '
            'output at 0')
